    max-width: 400px;
    position: relative;
  }

  .close-btn {
    position: absolute;
    top: 10px;
    right: 10px;
    background: transparent;
    border: none;
    color: white;
    font-size: 20px;
    cursor: pointer;
  }

  .card {
    background: #101010;
    /*width: 10em;*/
    height: 5rem;
    padding: 1.25rem;

    display: flex;
    flex-direction: column;
    justify-content: center; 
    align-items: center;
    
    transition: background 0.2s ease, transform 0.2s ease;
    border: 1px solid transparent; /* important */
    border-radius: 12px;
  }

  .card:hover {
    background: #151515;
    border: 1px solid #1DB954;
    border-width: 1px;
    border-radius: 12px;
    box-shadow: 0 0 8px rgba(29, 185, 84, 0.4);

    transition: all 0.4s ease;
    /*transform: translateY(-2px);*/
  }

  .value {
    color: #1DB954;
    font-family: "Outfit", sans-serif;
    font-size: 1.4rem;
    font-weight: 600;
    text-align: center;
 }

  .label {
    color: #FFFFFF;
    font-family: "Outfit", sans-serif;
    font-size: 0.8rem;
    font-weight: 600;
    text-align: center;
  }

  .mode-toggle {
    grid-area: toggle;
    display: flex;
    gap: 0.5rem;
    margin-top: 1rem;
    
  }

  .mode-toggle span:hover {
    color: #FFFFFF;
    background-color: #303030;
    transition: all 0.4s ease;
  }

  .mode-toggle label {
    cursor: pointer;
  }

  .mode-toggle input {
    display: none;
  }

  .mode-toggle span {
    padding: 6px 12px;
    border-radius: 14px;
    font-family: "Outfit", sans-serif;
    font-size: 0.75rem;
    background: #2a2a2a;
    color: #bbb;
    transition: all 0.2s ease;
  }

  .mode-toggle input:checked + span {
    background: #1DB954;
    color: white;
  }

  .slider-container {
    position: relative;
    justify-self: end;
    width: 260px;
    margin: 4px 20px;
    animation: fadeIn 0.25s ease;
  }

  /* Track */
  .slider-container input[type="range"] {
    width: 100%;
    appearance: none;
    height: 4px;
    border-radius: 2px;
    background: linear-gradient(
      to right,
      #1DB954 0%,
      #1DB954 var(--fill),
      #444 var(--fill),
      #444 100%
    );
    outline: none;
  }

  /* Hide default thumb */
  .slider-container input[type="range"]::-webkit-slider-thumb {
    appearance: none;
    width: 0.75rem;
    height: 0.75rem;
    border-radius: 50%;
    background: #202020;
    box-shadow: 0px 0px 2px 2px #1DB954;
    cursor: pointer;
  }

  .slider-container input[type="range"]::-moz-range-thumb {
    width: 0.75rem;
    height: 0.75rem;
    border-radius: 50%;
    background: #202020;
    box-shadow: 0px 0px 2px 2px #1DB954;
    border: none;
    cursor: pointer;
  }

  /* Custom thumb label */
  .thumb-label {
    position: absolute;
    top: -1.5rem;
    transform: translateX(-50%);
    background: #2A2A2A;
    border: 1px solid #1DB954;
    color: #1DB954;
    font-family: "Outfit", sans-serif;
    font-size: 0.675rem;
    padding: 5px 10px;
    border-radius: 14px;
    pointer-events: none;
    transition: left 0.1s ease-out;
    
    box-shadow: 0 0 8px rgba(29, 185, 84, 0.4);
    white-space: nowrap;
  }

  .detail1 {
    font-size: 1.4rem;
  }

  .detail2 {
    font-size: 0.8rem;
    color: #CCCCCC;
  }

  @keyframes fadeIn {
    from {
      opacity: 0;
      transform: translateY(-4px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }

  @media (max-width: 768px) {
    .kpi-controls {
      display: grid;
      grid-template-columns: 3fr 1fr;
      grid-template-areas:
        "title title"
        "slider toggle";
      gap: 0.75rem;
    }

    .kpi-controls h1 {
      grid-area: title;
    }

    .slider-area {
      grid-area: slider;
      justify-self: end;
    }

    .kpi-grid {
      grid-template-columns: repeat(3, 1fr);
      gap: 1.25rem;
      align-items: stretch;
    }

    .card {
      background: #101010;
      height: 4.5rem;
      padding: 1.25rem;

      display: flex;
      flex-direction: column;
      justify-content: center; 
      align-items: center;
    }

    .slider-container {
      width: 160px;
      margin: 4px 20px;
    }

    .mode-toggle {
      grid-area: toggle;
      justify-self: end;
    }
  }
  
  @media (max-width: 480px) {
    .kpi-wrapper {
      gap: 0rem;
    }

    .kpi-controls {
      grid-template-columns: 1fr 1fr;
      grid-template-areas:
        "title title"
        "buttons buttons"
        "slider toggle";
      gap: 0.5rem;
      column-gap: 0;
    }

    .kpi-controls h1 {
      grid-area: title;
      font-size: 1.25rem;
    }

    .top-buttons {
      grid-area: buttons;
