      justify-content: flex-end;
      gap: 8px;
    }

    .slider-area {
      grid-area: slider;
      justify-self: start;
    }

    .kpi-grid {
      grid-template-columns: repeat(2, 1fr);
      gap: 0.75rem;
      align-items: stretch;
    }

    .btn {
      width: 5.5rem;
      font-size: 0.625rem;
      font-weight: 400;
    }

