      font-size: 0.625rem;
      font-weight: 400;
    }

    .value {
      font-size: 1.2rem;
    }

    .label {
      font-size: 0.75rem;
    }
    
    .detail1 {
      font-size: 0.9rem;
    }

    .detail2 {
      font-size: 0.625rem;
      color: #CCCCCC;
    }

    .thumb-label {
      top: -1.25rem;
      font-size: 0.6rem;
      padding: 4px 8px;
    }
  }
</style>